export const LESSONS = {
  "rook": {"title":"车：横冲直撞","text":["车沿横线或直线走任意格数，不能越子。","车是重子，残局威力巨大；它还参与「王车易位」（后面会学）。"]},
  "bishop": {"title":"象：斜线飞行","text":["象沿斜线走任意格数，不能越子。","每个象一辈子只能走一种颜色的格子 —— 开局时你有一个浅格象和一个深格象。"]},
  "queen": {"title":"后：全能重炮","text":["后 = 车 + 象：横、竖、斜任意方向走任意格数，不能越子。","后是最强的棋子，但也因此最怕被白白换掉 —— 别过早出后。"]},
  "knight": {"title":"马：日字跳跃","text":["马走「日」字：直两格再拐一格（共 8 个方向）。","马是唯一可以越过其他棋子的棋子，没有「蹩马腿」。"]},
  "king": {"title":"王：一步一格","text":["王朝任意方向走一格。","王不能走进被对方攻击的格子（不能「送将」）—— 保护好它，它被将死对局就结束了。"]},
  "pawn": {"title":"兵：直走斜吃","text":["兵每次向前直走一格，永远不能后退。","首次移动时可以选择直进两格。","吃子方式特殊：斜前一格吃子，不能直着吃。"]},
  "promotion": {"title":"升变：小兵变后","text":["兵走到对方底线必须立刻升变为后、车、象或马（不能保持是兵，也不能变王）。","绝大多数时候升后；偶尔升马可以立刻将军，或升车/象避免逼和。"]},
  "castle": {"title":"王车易位：一步走两子","text":["王向车的方向横走两格，车跳到王的另一侧 —— 一步同时保王、出车。","条件：王和该车都没动过；两者之间无子；王不在将军中、不经过也不落在被攻击的格子。"]},
  "enpassant": {"title":"吃过路兵","text":["对方的兵刚用首步特权两格越过你兵的攻击格时，你可以在下一步立即像它只走了一格那样斜吃它 —— 这就是「吃过路兵」。","机会只有一回合，不马上吃就永久失效。"]},
  "values": {"title":"子力价值：别做亏本交换","text":["常用价值：兵 1 分 · 马/象 3 分（轻子）· 车 5 分 · 后 9 分；王无价 —— 丢了就输。","交换前先算账：用 3 分的马吃掉 5 分的车是赚的，用后换车就是大亏。"]},
  "protect": {"title":"吃子前先看保护","text":["能吃 ≠ 该吃：吃掉一个有保护的子，对方会立刻吃回来。","规则：吃子之前，数一数这个子有几个保护者 —— 用高价值的子去吃受保护的低价值子，几乎总是亏的。"]},
  "trade": {"title":"换子：什么时候划算","text":["「兑子」就是我吃你一个、你吃回我一个。划不划算，直接拿身价相减：**用 3 分的马换 5 分的车，净赚 2 分**；反过来就是亏 2 分。","只有一种情况例外要小心：**能吃不等于该吃**。吃之前先看一眼 —— 我吃完，对方能不能吃回来？能吃回来，就得把两边的分都算进去。","还有一条经验：**领先的时候多换子，落后的时候少换子**。你多一个车，盘上子越少，这个车越说了算。"]},
  "defend": {"title":"救受攻的子","text":["对方走完棋，先问自己：他在威胁什么？我的子是不是正被攻击？","被攻击的高价值子要马上处理：走开、有保护地防守、或者干脆吃掉攻击者。"]},
  "check": {"title":"将军与应将","text":["攻击对方的王叫「将军」。被将军的一方必须立刻解除，方法只有三种：走开王、用子阻挡、吃掉攻击子。","不存在「不理会将军」—— 界面只会让你选合法的应将走法。"]},
  "goal": {"title":"赢是「将死」，不是把子吃光","text":["**吃光对方的子不是目标，也从来不会发生。** 目标只有一个：把对方的**王将死** —— 王正被攻击（将军），而且**逃、挡、吃**三条路全没有。","王永远不会真的被吃掉：棋一到将死就结束了。所以王没有身价，也不能被拿去交换。","还有一种结局是**和棋**：轮到走却没有合法着且没被将军（逼和）、子力不足以将死、双方同意，等等。和棋各得半分 —— 输棋的一方常常是靠它救回来的。"]},
  "mate": {"title":"将死：终结对局","text":["被将军且无任何合法应对 = 将死，对局立即结束，将死方获胜。","最常见的杀型之一是「底线杀」：王被自己的兵挡住退路，重子在底线将军。","想多练杀型？去「模式 → 做题」，一步杀/两步杀题库等着你。"]},
  "stalemate": {"title":"逼和：大优也会和棋","text":["轮到一方走棋、没被将军、却一步合法棋都没有 = 逼和，判和棋！","大占优势时最容易随手逼和，葬送胜局 —— 永远给对方王留一条「合法的活路」直到将死它。"]},
  "ladder": {"title":"双车阶梯杀","text":["两个重子（车/后）轮流「封线 + 将军」，像爬梯子一样把对方王一排一排推到边线将死 —— 这是最容易掌握的必杀技术。","口诀：一个封住王的去路，另一个从旁边一线将军；王退一排，就再爬一档。"]},
  "qrladder": {"title":"后车配合：绞杀边线","text":["后 + 车打阶梯和双车一样，而且后封线更严密 —— 但也更容易随手逼和，记得永远给王留活路直到将死。","阶梯是「把王赶到边上」这一类的代表。接下来四课换个思路：**王已经在边上或角上了，怎么一步收网**。"]},
  "drill-queen": {"title":"后杀单王（引擎陪练）","text":["K+Q 对单王是最基础的必胜残局，三步套路：① 后保持与黑王「马步」距离，一圈圈锁死它；② 自己的王走近助攻；③ 王到位后在边线将死。","「马步」距离是防逼和的保险：后既锁住王，又永远不会贴脸没收它的最后一格。卡住时点顶栏「提示」。"]},
  "drill-rook": {"title":"车杀单王（引擎陪练）","text":["K+R 对单王同样必胜，但更考验步法：① 车封一条线当栅栏，把黑王限制在越来越小的区域；② 自己的王走近，与黑王正面「对王」；③ 对上王的那一刻，车将军就是将死或再逼近一线。","完成这一课，你就掌握了最重要的两个基础残局 —— 去人机·新手开始第一局（它会主动犯错，专为第一局准备），或到「做题」模式继续磨杀型！"]},
  "backrank": {"title":"底线杀：被自己的兵闷死","text":["**实战里最常见的杀型，而且多半发生在双方都没注意的时候。** 王易位到 g1/g8 之后，前面三个兵一个没动 —— 它们挡住了自己王唯一的出口。","这时一个车或后冲到底线将军，王**上不去**（兵挡着）、**躲不开**（左右都在车的火力线上），就是将死。整个过程一个子都不用牺牲。","防它也只要一步：**提前推一个兵**（常见的是 h 兵），给王开一扇「气窗」。老手在没事的时候就会顺手推掉。"]},
  "qkiss": {"title":"后贴脸杀：靠上去，但要有人撑","text":["后**紧贴**着对方的王将军，叫「贴脸」。后能同时封住王周围一圈格子，所以王往往一格都走不了。","关键在**撑腰**：后贴上去自己也在王的攻击范围里，**必须有另一个子保护这个格子**，否则黑王一口吃掉，你白送一个后。这一课的撑腰角色是 h6 的象 —— 它从侧面死死盯住 g7。","所以贴脸杀的检查清单只有两条：**后贴得上去吗？那一格有人保护吗？** 两条都是「是」，才是杀；只有第一条，那是送后。"]},
  "smother": {"title":"闷杀：马的绝技","text":["王被自己的棋子围得水泄不通时，一次将军就是将死 —— 马是唯一能「隔着子将军」的棋子，所以闷杀几乎是马的专利。","标准画面：王缩在角落，旁边全是自己人，马跳到 f7（或 f2）一锤定音。"]},
  "tc-smother": {"title":"闷杀实战：先逼进角，再堵门","text":["「杀型积木」里你见过闷杀的形状。实战里它很少现成摆好 —— 通常要先**用将军把王逼进角落**，再让对方自己的子堵住出口。","这个局面黑王已经在 h8，g8 车和 g7、h7 兵把它围得严严实实。这正是马最喜欢的形状：一步 Nf7，无处可逃。","识别信号：**王在角上、旁边全是自己人**。看见这个，就找马。"]},
  "arabian": {"title":"阿拉伯杀：车和马的老搭档","text":["**车 + 马**是配合最好的一对杀棋组合，因为它们的火力形状完全不重叠 —— 马管得住车管不到的斜角。","标准形状：王在角上，**马站在离角两格的位置**（比如王 h8、马 f6），它一个子就同时看住了 **g8** 和 **h7**。车再冲到 h7 将军，车本身由马保护着。","记法很简单：**马先就位盖住两个逃跑口，车最后进来将军。** 顺序反了，车会被白吃。"]},
  "drill-bishops": {"title":"双象杀单王（引擎陪练）","text":["两个象控制两种颜色的格子，配合王可以把对方王逼进**角落**将死 —— 注意：必须逼到象能控制的那个角（与其中一象同色的角）。","步骤：两象并肩站在相邻斜线上织成一张网，王在后面把黑王一格格推向角落。"]},
  "fork": {"title":"捉双：一子攻两个","text":["一个子同时攻击对方两个目标，叫「捉双」—— 对方只救得了一个。","带将军的捉双最凶：对方必须先应将，另一个目标就归你了。马是捉双大师（它的攻击别人挡不住）。"]},
  "pin": {"title":"牵制：动不了的子","text":["如果一个子走开会让自己的王暴露在将军之下，规则禁止它移动 —— 这个子被「牵制」了。","被完全牵制的子点击后不会亮出任何落点 —— 不是出了故障，是规则不允许。破解：走开王离开牵制线、挡住牵制线，或吃掉牵制子。"]},
  "skewer": {"title":"串击：逼开前面吃后面","text":["串击是牵制的反面：攻击一条线上**前面**的高价值子，逼它让开，再吃它**身后**的子。","最狠的是「王在前」的串击 —— 将军！王必须让位，身后的子就归你了。"]},
  "tc-skewer": {"title":"串击实战：王在前面，后在后面","text":["串击是「先攻前面的大子，逼它让开，再吃后面的」。最强的串击是**王在前面**：王必须应将，后面的子就没人管。","黑王 e5、黑后 e8 在同一条直线上，你的车只要上 e 线将军，王一走，后就是你的。","找串击的方法：**看对方的王和后有没有站在同一条线上**，再看自己有没有子能占到那条线。"]},
  "discovery": {"title":"闪击：挪一子，露一击","text":["一个子挪开，让它**身后**同线的子发起攻击，叫「闪击」。挪开的子还能顺手吃子或占位 —— 一步两用。","最强的是「闪将」：挪子露出的是**将军**。对方只能应将，挪开的子抢到的东西保不住了。"]},
  "remove": {"title":"消除防守者：直接把守家的子吃掉","text":["调走守家的子有两种办法：逼它走开（引离），或者**干脆吃掉它**。","换子的时候多问一句：我吃掉的这个子，正在守着什么？它一消失，那样东西就归你了。"]},
  "deflect": {"title":"引离：把守家的子调走","text":["一个子之所以安全，常常是因为**有别的子在守它**。想吃它，不一定要正面强攻 —— 先想办法把守它的那个子**调走**。","最干脆的调法是将军：对方必须应将，守家的子被迫离开岗位，你要吃的东西就没人管了。"]},
  "overload": {"title":"过载：一个子干不了两份活","text":["一个子同时守两样东西，叫「过载」。它看上去两边都顾得上，其实**只要逼它顾一边，另一边就塌了**。","看到对方某个子身兼两职，就去攻它守着的其中一样 —— 它救得了这个，救不了那个。"]},
  "tc-overload": {"title":"过载实战：先兑掉一个，再拿另一个","text":["黑后在 d7 同时守着 e8 车和 d5 马。**一个子干不了两份活**：你先在一处兑掉它，它就顾不上另一处。","Rxe8+ 逼黑后吃回 —— 它一到 e8，d5 的马就没人守了，Qxd5。","过载的解法总是同一个顺序：**先动被守的两个目标中「带将军的那个」**，再收另一个。"]},
  "decoy": {"title":"引入：把子骗到你想要它待的格","text":["引离是把子**赶走**，引入正相反 —— 把子**骗过来**，骗到一个它站上去就要倒霉的格子。","常见的做法是弃子将军：对方不得不吃，而吃完之后，他的王正好站进了你的马叉里。"]},
  "tc-decoy": {"title":"引入 + 捉双：先把王骗过去","text":["捉双要成立，两个目标得站在马的「日」字上。目标不在？**把它请过去**。","这里黑王在 g8、后在 d8，马在 e5 —— 从 f7 跳能同时攻到 h8 和 d8。所以先 Rh8+！黑王只能吃车（f8 被 a3 象封着），一到 h8，Nxf7+ 就叉住王和后。","一车换一后加一兵，这就是**弃子引入**：牺牲的子把对方的王送到捉双的位置上。"]},
  "interfere": {"title":"拦截：把守家的那条线切断","text":["守家的子靠一条线看住目标 —— 横线、竖线或斜线。**在这条线中间插一个子**，视线一断，目标就失守了。","插进去的子往往会被吃，所以要么它有人保护，要么吃它的代价比丢掉目标更大。"]},
  "tc-interference": {"title":"拦截实战：切断守卫的视线","text":["黑后在 b7 远远守着 g7，你的后已经到了 h6 —— 只差把这条第 7 横线**切断**。","d5 的马一动就是闪将（c4 象照到 g8）。跳到 e7 或 c7，马正好站在 b7 和 g7 之间：黑王只能退 h8，然后 Qxg7 将死 —— 黑后隔着马，救不到。Nf6+ 也行：马撑住 h7，Qxh7 将死。","拦截的本质：**找到守卫的那条线，把一个子插进去**，最好还带着将军。"]},
  "tc-zwischenzug": {"title":"中间着：先将军，再吃回来","text":["对方刚吃了你一个子，你的本能是**立刻吃回来**。可有时候在吃回来之前，还能先插进一步「非应不可」的棋 —— 通常是将军 —— 这一步叫**中间着**。","这里黑象刚吃到 f3，你的 c4 象同时被 b5 兵攻击。直接 gxf3 吃回，黑就 bxc4 拿走你的象。先 Bxf7+ 将军：象反正保不住，换成一个兵**外加一次将军**，黑王被迫应将，你再从容 gxf3。","口诀：**被吃之后别急着吃回，先看有没有带将军的棋**。"]},
  "cl-inter": {"title":"中间着：吃回之前先插一步","text":["吃子交换通常是你吃我、我吃你。可在吃回之前，如果有一步对方**非应不可**的棋（将军、捉后），就先插进去 —— 这叫**中间着**。","算交换的习惯：**每到该吃回的时候，先看看有没有更强的中间着**。它常常把「一换一」变成「白赚一个」。","这一课前两步是同一个局面：先将军吃车，再把另一个车吃回。最后一个局面，也是先将军再吃。"]},
  "po-trap": {"title":"没有退路的子会被捉死","text":["一个子站得再凶，**没有退路**也危险：只要用一个兵去攻击它，它就只能送掉。","找被困的子：看它能去的每一个格子 —— 被兵看着的、被自己人占着的，一个个划掉。**剩下零个格子，就找一个兵去捉它。**","下面三个局面，被困的都是象。"]},
  "cl-quiet": {"title":"安静的一着：不将军、不吃子也能赢","text":["强制着都看完了，还没找到好棋？再看**安静的一着**：它不将军、不吃子，却留下一个对方挡不住的威胁。","这种棋最容易漏看，因为它看起来什么都没做。找它的办法是反过来问：**如果我能连走两步，第二步走什么？**然后看第一步能不能为它做好准备。","下面三题的答案都是一步安静的棋，每一步背后都藏着下一步的致命威胁。"]},
  "cl-threat": {"title":"先问：对方想干什么","text":["对方刚走完一步，先别急着想自己的计划，**先问一句：他下一步想干什么？**","这三个局面里，黑方的答案都一样：在 g2 将死。挡住它还不够 —— **最好的防守，同时也在反击**。","看清威胁以后再列候选着：哪一步能守住 g2，还能顺手打到对方？"]},
  "cl-cands": {"title":"候选着：先列三步，再选一步","text":["看到一步好棋就想马上走，这是最常见的毛病。强手动手之前，先把**值得考虑的几步 —— 候选着 —— 都列出来**，再一步一步比较。","列的时候照一个固定的顺序问：有没有将军？有没有吃子？有没有威胁？最后才是普通的调动。第一眼看到的那步常常不是最好的，有时还是输棋。","这一课的三个局面，第一眼的那步都不对。先列出候选着，再选。"]},
  "cl-order": {"title":"强制着优先：将军、吃子、威胁","text":["对方能选的应着越少，你就越容易算清楚。**将军**逼他应将，**吃子**逼他考虑吃回，**威胁**逼他去防守 —— 这三种棋叫**强制着**。","所以列候选着的顺序是：**先将军，再吃子，最后看威胁**。三种都要看完，不能只看第一种：白白送子的将军不是好棋。","下面三题，依次是用将军、用吃子、用威胁取胜。"]},
  "cl-count": {"title":"吃之前数一数：攻几次，守几次","text":["一个子被攻击几次、被保护几次，吃之前先数清楚：**攻击的次数多于保护的次数，才赢得下它**。","数完次数还要看价值：**先用最便宜的子去吃**。用车去换对方的马，就算最后吃到了，也是亏的。","对方吃回来的时候也在数，所以要一直数到最后一次吃子为止。"]},
  "cl-checks": {"title":"每一步将军都要看，包括送子的","text":["列将军的时候，别只看安全的那几步。**把后送到对方嘴边的将军也要算**：对方被迫吃掉它，下一步往往就是杀。","判断方法很简单：对方的应将办法只剩一两种时，就沿着这一两种往下算。只要每条路都走向将死，送掉后也是赚的。","这一课两个经典杀法：闷杀（后送到 g8，马来收官）和底线杀（后送到 e8，车来收官）。"]},
  "cl-mate": {"title":"连续将军：一路算到将死","text":["对方只能动王的时候，**连续将军**是最好算的变化：每一步他只有一两种应法，你可以一直算到将死。","这一课的杀法要算三步：先弃车把王引到 h8，再用后将军，最后在 g7 将死 —— f6 兵守着 g7。","**弃子之前先把整条线算完**：只要中途有一步对方能逃掉，弃掉的车就白送了。"]},
  "cl-race": {"title":"数步数：兵的赛跑","text":["兵的赛跑靠的不是感觉，是**数步数**：你的兵还要几步升变？他的兵还要几步？轮到谁走？","别忘了王也在跑：**王的一步可以同时做两件事** —— 既追对方的兵，又护送自己的兵。","第一题是著名的雷蒂习题：看起来追不上的兵，王斜着走也能追上。后两题先数清楚，再走。"]},
  "cl-end": {"title":"算到底：别在半路停下","text":["算变化最常见的错，是**算到一半就停**：「他吃掉我的后 —— 不行。」可是再往下走两步，结果可能完全相反。","规则是：**一直算到局面安静下来** —— 没有将军，没有能吃的子，没有悬着的威胁 —— 再数一数谁多谁少。","这一课是一整条线：你把车放到 d4，黑方吃掉你的后。别停，接着算。"]},
  "cl-replies": {"title":"把对方的每一种回答都列出来","text":["算强制着的时候，要把对方**每一种合法的回答**都列出来，一个都不能漏。漏掉的那一种，往往正是对方唯一的活路。","这一课是著名的「希腊礼物」：Bxh7+ 送象，Ng5+ 追将，Qh5 上后。每走一步，先数一数黑方能怎么应。","**将军之后，对方通常只剩两三种应法**；把每一种都算到底，送子才有把握。"]},
  "cl-guard": {"title":"谁在守？先吃掉守卫","text":["对方的子被保护着，吃不动？先看**是谁在保护它** —— 把那个守卫吃掉（或引开），原来的目标就没人管了。","算的顺序：找到目标，数它的保护者，再看能不能**先吃保护者**。常常是先吃一个，再吃一个。","前两步是同一个局面的两步；最后一个局面，要找那个守着 d8 车的马。"]},
  "opening": {"title":"开局三原则","text":["原则一：抢占中心 —— d4/e4/d5/e5 四格是全盘要冲，子力越靠近中心控制力越强。","原则二：快出轻子 —— 先出马和象，别反复走同一个子，别过早出动后。","原则三：尽早易位 —— 把王藏进角落，车也顺势出动（就是前面学过的王车易位）。"]},
  "op-firstmove": {"title":"第一步：一步棋同时做三件事","text":["开局第一步几乎总是 **e4 或 d4**。不是因为约定俗成，而是因为这一步同时做成三件事：占住中心、给象让出斜线、给后让出斜线。","开局时白方 20 个合法着法里，**f1 象和 d1 后一个都动不了** —— 它们被自己的兵挡得死死的。推一步 e4，象立刻有 5 个格子可去，后有 4 个。一步棋放出两个大子。","推边兵（a4、h4 之类）一件也做不成：不碰中心，不给谁让路，还在自己王的旁边留了个洞。"]},
  "op-knights": {"title":"马往中心跳，别往边上跳","text":["「马在边上是废物」是句老话，而且能数出来：**空盘上，马站在 f3 能去 8 个格子，站在 h3 只能去 4 个** —— 整整少一半。","所以开局出马，几乎总是 **Nf3 和 Nc3**（黑方对应 Nf6、Nc6）。这两格既靠中心，又正好盯住中心格。","Na3、Nh3 这种边上的马，不但控制的格子少，还挡不住对方的中心，下一步往往还得再挪一次 —— 等于白走一步。"]},
  "op-tempo": {"title":"开局一个子只走一次","text":["开局比的是**谁先把子力摆好**。你每走一步，只有把一个新的子带出来，才算真的赚到；把已经出来的子挪来挪去，等于原地踏步。","最常见的赔本买卖是**被追着走**：子出得太早、位置又不安全，对方一边攻你一边出子。你挪一步，他出一个子 —— 挪三次，他就多出三个子。","所以出子之前先想一句：**这一格，它待得住吗？** 待不住的位置，早出去就是白送步数。"]},
  "op-castle": {"title":"别拖易位：中路一开，王最怕待在中间","text":["开局阶段中心的兵会互相吃掉，e 线和 d 线迟早会打开。**线一开，还站在 e1/e8 的王就正对着对方的车和后。**","所以易位不是「有空再说」，而是开局三件事里有明确期限的一件：**通常在头 10 步之内完成**。轻子出来两三个，就该易位了。","反过来也一样：看到对方的王迟迟不易位，就该想办法把中路撬开 —— 那是他最脆弱的地方。"]},
  "op-pawnmoves": {"title":"兵推出去就收不回来","text":["所有棋子里只有兵**不能后退**。别的子走错了还能挪回来，兵推出去就是永久的 —— 它身后留下的格子，这盘棋再也守不住了。","所以开局推兵要省着用：通常就是**中心那一两个兵**，用来占中心和给子力让路。多推一个兵，就多一个补不回来的洞。","王前面的兵尤其要小心。易位之后 f、g、h 三个兵是王的屋顶，随手推一个，屋顶就漏了。"]},
  "op-italian": {"title":"你的第一个开局：意大利","text":["把三原则连起来走，就是一个真正的开局。最适合入门的一个叫**意大利开局**：1.e4 e5 2.Nf3 Nc6 3.Bc4。","三步棋，三件事，一步不浪费：**e4 占中心并放出象和后；Nf3 出子并攻 e5；Bc4 出子并瞄准 f7**（黑王前面唯一只有王护着的软肋）。黑方照样子应对，棋就是均势。","开局不用背。记住它每一步在干什么，遇到对方走别的，你也照三原则应付得了。想背线路的话，做题里的「开局」一档有 109 条主变，按 ECO 排好了。"]},
  "firstgame": {"title":"第一盘完整棋：学者杀","text":["把开局原则串成一盘真棋 —— 顺便认识最著名的开局陷阱「学者杀」：4 步将死不设防的对手。","它靠的是双子夹击 f7（黑方王前只有王保护的软肋）。但记住：对手只要应对正确（如 g6 + Nf6），早出的后反而会被追着打 —— 所以它是用来「认识」的，不是用来依赖的。"]},
  "square": {"title":"方块规则：追不追得上兵","text":["兵要走几步到底线，就以这几格为边长，从兵所在格向底线方向画一个正方形 —— 这就是兵的「方块」。","**轮到防守方走时**，只要王能踏进这个方块，就一定追得上兵；进不去，兵就一定升变。不用一步步算，画个方块就知道结果。","反过来对进攻方也一样：兵每往前一步，方块就缩小一圈，对方王可能就被关在外面了。"]},
  "opposition": {"title":"对王：谁先让开谁吃亏","text":["两个王在同一条线上、正中间只隔一格，谁都不能再靠近 —— 这叫「对王」（opposition）。","关键在于：**轮到谁走，谁就必须先让开**。所以「取得对王」就是把走棋的义务丢给对方，自己反而占了先。","王兵残局的胜负常常只差这一手：王在兵前面还不够，还要拿到对王。拿不到时，就用兵走一步「等一着」，把义务还给对方。"]},
  "keysquares": {"title":"关键格：王站对了，兵一定进","text":["王兵对单王，胜负不取决于兵走得多快，而取决于**王能不能站到对的格子上**。这些格子叫「关键格」。","兵过了第 4 横线之后，它的关键格就是正前方那三格。以 e5 兵为例，关键格是 d6、e6、f6 —— 白王只要占住其中任何一个，不管轮谁走，这个兵一定能升变。","所以王兵残局的正确下法是：**先把王送上关键格，兵最后再推**。反过来先推兵、王跟在后面，常常就只能和棋。"]},
  "kingactive": {"title":"残局里，王是主力","text":["中局要把王藏好，残局正相反：子力换得差不多之后，**王是一个能攻能守的强子，不出来就等于少一个子在下棋**。","王在残局里的价值大约相当于一个象多一点。它能护送自己的兵、能挡住对方的兵、能一格一格把对方的王逼开 —— 这些事别的子都替不了。","所以残局的第一个念头往往不是走兵，而是：**我的王现在该往哪儿走**。往中心走，往兵多的一边走，往对方通路兵的必经之路上走。"]},
  "eg-kingact": {"title":"王要出动：残局里它是主力","text":["中局里王要躲，残局里王要**冲到前面**。棋盘上没了后和大子，王就是最强的进攻单位。","这个王兵残局双方兵数相同，赢家是**王先到中心的那一方**。第一步就是把王从 g1 挪出来，向 e3、d4 走。","口诀：**大子一换光，王就往中间走**。"]},
  "drill-pawn": {"title":"王兵残局：护送升变（引擎陪练）","text":["K+P 对单王是最常见的残局：王走在兵的**前面**开路，抢住兵前方的关键格（与对方王「对王」），小兵才推得过去。","王先行、兵慢推；升变成功即获胜 —— 小心别把对方王憋成逼和。卡住时点顶栏「提示」看引擎推荐。"]},
  "majority": {"title":"兵多的一侧：先推没人挡的那个兵","text":["一侧的兵比对方多，叫「多数兵」。多数兵的价值不在于多，而在于**能挤出一个通路兵**。","推法有讲究：**先推那个对面没有兵挡着的兵**（叫「候补兵」）。它一路无阻，能把对方的兵逼得动起来，后面的兵才跟得上去；先推被挡住的那个，只会把自己堵死。","反过来防守也是这条：对方开始推候补兵时，别急着用兵去顶 —— 顶上去往往正合他意。"]},
  "pawntrade": {"title":"多子兑子，少子兑兵","text":["残局里最实用的一条交换原则：**自己多子的时候换子，自己少子的时候换兵**。","多子方换掉一对子，剩下的子力比例就更悬殊 —— 多一个兵在满盘子力里不算什么，换到只剩王和兵，那一个兵就是胜负。少子方反过来：兵换光了，对方多的那个兵也就没用了。","所以拿着多一个兵的残局，看到能换的子就换；反过来落后一个兵，要死死抓住自己的兵不放，宁可换掉车和象。"]},
  "rookbehind": {"title":"车要放在通路兵后面","text":["车兵残局有一条几乎不出错的规矩：**车放在通路兵的后面**。自己的兵后面，或者对方的兵后面，都算。","道理在于兵每往前走一步，后面的车射程不变、而前面挡路的车能站的格子越来越少。**推兵的一方越推越强，挡兵的一方越挡越憋。**","所以看到通路兵，先问一句：我的车在它后面吗？对方的车又在哪里？这一个问题常常就决定了这盘残局。"]},
  "eg-cutoff": {"title":"切断：不让王靠近你的兵","text":["车兵残局第一课不是推兵，是**把对方的王关在门外**。车横在一条横线上，对方的王就永远过不来。","这里黑王在 e8，你的车上到 h7 之后，第 7 横线整条归你 —— 黑王只能在最后一排徘徊，你的王和兵慢慢推上去。","记住：**先切断，再推兵**。切得越远，王越无能为力。"]},
  "wrongbishop": {"title":"错色象：多一个象也和棋","text":["边线兵（a 兵或 h 兵）加一个象，是残局里最有名的陷阱：**如果象控制不到升变格，防守方的王只要坐进那个角，就是和棋** —— 多一个整子也赢不了。","原因很简单：兵只能从这一条边线升变，升变格的颜色是固定的。象走单色格，颜色不对就永远踏不上那一格，也就永远赶不走坐在角里的王。","所以拿到这种残局要先看两件事：**升变格是什么颜色，我的象是什么颜色**。反过来轮到自己防守，就认准那个角往里钻。"]},
  "eg-rook7": {"title":"车占第 7 横线：吃兵，困王","text":["残局里车最好的位置之一是**对方的第 7 横线**：那里通常摆着一排没动过的兵，而对方的王被压在底线。","Rd7 之后 b7 兵就在你嘴边，黑王也被封在第 8 横线。对方要防你就得把车拉回来做被动的守卫。","看见空开的直线，先想：**能不能从这条线冲到第 7 横线？**"]},
  "drill-lucena": {"title":"卢塞纳：车兵残局搭桥","text":["「卢塞纳」是车兵残局最重要的**取胜**技术：己方王站在兵前挡路、对方车在后面不停将军时，用自己的车在第 4 横线**搭一座桥**替王挡住将军，王就能让开、兵顺利升变。","记住三步：① 把车放到兵前方第 4 横线；② 王从兵前挪出来；③ 对方将军时用车在中间挡一手（这就是「桥」）。"]},
  "drill-philidor": {"title":"菲利多尔：车兵残局守和","text":["残局不只有赢，更要会**守**。「菲利多尔防守」是少一兵时求和的看家本领：把车横在自己的**第 3 横线**上，对方的王就过不来；等它的兵推到第 3 横线时，立刻把车撤到底线，从**背后连续将军**。","这一课你执白**少一个兵**，目标不是取胜而是**守成和棋** —— 逼和、子力不足、50 回合无进展都算成功。"]},
  "eg-bvn": {"title":"象对马：象能从远处困住马","text":["棋盘开阔、两翼都有兵时，**象强过马**：象一步管一条长斜线，马要走好几步才能换一翼。","更妙的是象能**困住**马。h8 的黑马只有 g6 和 f7 两个出口，它们在同一条斜线上 —— 象到 h5 一格就全封死。然后你的王慢慢走过去吃它。","看见对方的马在边角上，先数它有几个出口，再看**一个象能不能同时盯住它们**。"]},
  "eg-nvrp": {"title":"马守边兵：钻进角落也能和","text":["只剩一个马对一个边兵，马守得住吗？守得住 —— 但要知道一个怪招。","黑王 b2 正要赶走 b3 的马，然后 a1 升后。Na1！马钻进升变格：黑王吃它（Kxa1）之后，你的王 Kc2，黑方**没有棋可走**，逼和。黑王不吃，你的马就守在那里。","残局里不要只想「保住子」——**能把局面走成逼和的子，比活着的子更值钱**。"]},
  "eg-rvminor": {"title":"车对马：马离王越远越危险","text":["单车对单马通常和棋 —— **只要马待在自己王的身边**。马一旦被赶到远处的角落，车和王合力就能困住它。","a1 的黑马只有 b3 和 c2 两个出口。Rb2！车守 b 线管住 b3，第 2 横线管住 c2 —— 马一步也动不了，下一步就被吃。","用马防守时记住：**别让马离开王**；用车进攻时记住：**先困住，再吃**。"]},
  "eg-qvp": {"title":"后对七线兵：将军，逼王站到兵前","text":["对方的兵到了第 7 横线，你的后要赢它，靠的是一个节奏：**不停将军，直到黑王被迫站到兵的前面**（e1），那一刻兵动不了，你的王走近一步。","然后再重复：将军、逼王挡兵、王走近 —— 直到你的王也来到跟前吃掉兵。","现在就开始：随便一步能将到 d2 王的棋都是好的起手。"]},
  "eg-queen": {"title":"后残局：将军顺手吃兵","text":["后残局里最实用的技术是**带将军的吃兵**：先将军，王一躲，后就顺路吃掉一个没人守的兵。对方全程没有还手的时间。","黑方 a7、h7 两个兵都没人守。Qh5+ 或 Qa4+，黑王一躲，下一步就吃兵。","后残局找棋的顺序：**先找将军，再看将军后能顺路吃到什么**。"]},
  "mg-plan": {"title":"开完局之后：先问三个问题","text":["开局结束的标志是：轻子都出来了，王已经易位，车之间没有别的子挡着。接下来没有现成的口诀，只有三个问题。","一问王安全吗 —— 自己的和对方的。二问我哪个子最差 —— 站得最憋屈的那个，下一步就该轮到它。三问对方在图谋什么 —— 他上一步是冲着哪里去的。","中局不是「想出妙手」，是把最差的子换个地方站。妙手是这么攒出来的。"]},
  "mg-trade": {"title":"什么时候该兑子","text":["兑子不是「打平」，它总是对某一方更有利，关键看你处在哪一边。","多子的时候兑子不兑兵：场上子越少，你多出来的那个子越显眼，最后剩它一个横着走。少子的时候正好相反 —— 留住子力，把局面搅复杂。","还有一种情况：自己的子挤在一起施展不开，就主动兑掉一两个，给剩下的子腾地方。"]},
  "mg-openfile": {"title":"开放线：车的高速公路","text":["一条直线上双方都没有兵，就叫「开放线」。车在自己的底线上几乎没用，一站上开放线就能一路打到对方家里。","所以兑掉兵之后的第一件事，往往就是把车调到刚刚空出来的那条线上。两个车叠在同一条开放线上更凶，叫「叠车」。","记一句话：兵开路，车跟进。"]},
  "po-file": {"title":"车占开放线，再把车叠起来","text":["一条线上一个兵都没有，叫**开放线**。车在开放线上能一直走到对方的底线或第 7 横线。","**先占线，再叠车**：两个车叠在同一条开放线上，力量加倍，对方很难同时挡住两个。","三个局面：b 线、c 线、g 线各一条开放线，都是叠车。"]},
  "mg-outpost": {"title":"前哨：马站上赶不走的格","text":["如果对方左右两条线上的兵都没了，那个格子就再也没有兵能来赶你 —— 这叫「前哨」。","马最适合占前哨：它跳得慢，一旦站稳就长期起作用，而且是唯一能越过别的子的兵种。象和车在前哨上也很舒服。","看兵型找前哨：哪里缺了兵，哪里就有洞。"]},
  "po-outpost": {"title":"前哨：马站上去就赶不走","text":["**前哨**是对方的兵永远赶不走、你的兵又能保护的格子。马最喜欢前哨：从那里，它同时攻击好几个方向。","判断一个格子是不是前哨：看它两侧的线上，对方还有没有能走上来攻击它的兵。没有了，这个格子就是你的。","三个局面里，马跳上前哨以后都有立刻的收获。"]},
  "po-hole": {"title":"弱格：兵再也守不到的格子","text":["兵只能往前走，所以它身后的格子一旦没有兵能守，就永远守不回来了 —— 这样的格子叫**弱格**，也叫空洞。","黑方的 g 兵推到 g6 以后，f6 再也没有黑兵能守；你的兵站在 g5，还能把马稳稳托在 f6。**把马放进对方的空洞，它就赶不走了。**","三个局面都是同一个空洞 f6，看看马站上去以后能打到什么。"]},
  "mg-pawns": {"title":"兵型：叠兵、孤兵、洞","text":["兵是全盘唯一不能后退的子，所以兵一走，留下的弱点就是永久的。看懂兵型，就等于看懂了这盘棋的长期走向。","叠兵：同一条线上两个自己的兵，前面那个挡住后面那个，两个都走不动，还互相帮不上忙。","孤兵：左右相邻两条线上都没有己方的兵，没有任何兵能保护它，只能靠大子看着 —— 大子被拴住了，就等于少了一个子。"]},
  "ps-doubled": {"title":"叠兵：两个兵，一份活","text":["c6 和 c7 两个兵叠在同一条线上，这叫**叠兵**。前面的挡住后面的，后面的守不了前面的 —— 两个兵只顶一个用，而且后面那个（c7）永远没人守。","黑虽多一个兵，但你的车能沿 d 线冲到第 7 横线：Rd7 直接吃到 c7 头上。","评估兵多兵少时，**叠兵、孤兵都要打折**。"]},
  "ps-iqp": {"title":"孤兵：要么突破，要么被围","text":["d4 兵两边的 c 线、e 线都没有自己的兵 —— 这是**孤兵**。它守不住，但它换来的是空间和活跃的子力。","有孤兵的一方只有一个计划：**在被围死之前突破**。d4–d5！开线、开斜线，让子力全部活起来。","对方的计划正相反：牢牢占住 d5 格（在孤兵前面放一个马），然后慢慢围攻它。"]},
  "ps-hanging": {"title":"悬兵：c4 + d4 并肩站","text":["c4、d4 两个兵并排站着，两侧都没有自己的兵 —— 这叫**悬兵**。它们并肩时控制着 b5、c5、d5、e5 一整排格子，很有力。","悬兵的弱点是**被迫动一个**：一动就露出空档。所以主动方要在对方施压之前自己选时机推进：d5！打开局面。","遇到对方的悬兵，就用子力压它，逼它动；自己有悬兵，就趁子力活跃时**主动推**。"]},
  "mg-passer": {"title":"通路兵：会自己长大的子","text":["一个兵前面那条线上没有敌兵，左右相邻两条线上也没有敌兵挡在它前方 —— 它就是「通路兵」，一路走到底就变成后。","通路兵越往前越值钱，而且它逼得对方必须留人看着，等于对方少一个子在别处打仗。","所以中局兑子的时候要顺手算一笔账：兑完之后谁有通路兵。有通路兵的一方，进入残局往往就赢了。"]},
  "po-major": {"title":"多兵的一翼：造出通路兵","text":["一翼上你的兵比对方多，这一翼就能造出**通路兵** —— 前面和两旁都没有对方的兵能挡、能吃的兵。","办法是**让兵去撞兵**：多的一方推兵，逼对方兑换，兑到最后，多出来的那个兵就通了。**先推前面没有对手挡着的那个兵。**","残局里，一个远方的通路兵常常就是一整盘棋。"]},
  "po-behind": {"title":"车在通路兵的后面","text":["通路兵往前走的时候，车放在哪里最好？**放在它后面。**车在兵后面，兵每前进一步，车管的线就长一步。","车放在兵前面，兵越走车越被挤；你的车在兵后面推，对方的车挡在前面，兵照样推得动。","这条规则叫**塔拉什规则**：车在通路兵后面 —— 自己的通路兵是这样，对方的也是这样。"]},
  "mg-attack": {"title":"王翼进攻：先集结，再冲锋","text":["进攻不是靠一个子发狠，是靠人多。规矩很朴素：你在王那一侧的子，要比对方守在那里的子多。","所以真正的进攻是从「调子」开始的 —— 每一步都往那个方向再加一个子，加到比对方多为止，再动手。手上只有两个子就冲的，基本都被反打。","对方王前的兵一旦动过（比如走了 h6、g6），那里就有了抓手 —— 那正是要数人头的地方。"]},
  "po-kpend": {"title":"何时换子：换成必胜的兵残局","text":["**兵残局是算得最清楚的残局**：没有子力，只剩王和兵，谁赢谁和，常常能一步一步数出来。","所以换子之前先问：换完以后的兵残局，是不是**我能数出来的赢棋**？看两样：谁的王更靠前，谁有**远方通路兵** —— 离对方王很远的通路兵。","三个局面：换车、换后、再换车，都换成了赢的兵残局。"]},
  "po-trade": {"title":"何时换子：象换掉以后，王先冲进去","text":["小子换小子也一样，先算换完的兵残局：**换完以后谁的王先冲进对方的兵里，谁就赢。**","另一个换子的理由：对方的象正在保护或护送一个危险的兵 —— 换掉它，那个兵就没人管了。","三个局面都是象换象，换完就是赢的王兵残局。"]},
  "ps-chain": {"title":"兵链：打它的底座","text":["黑兵 e5、d6 斜着连成一条**兵链**：e5 靠 d6 守，d6 靠 c7 守。链子最结实的地方是头（e5），最脆的地方是**底座**。","所以不要去撞头，去撬底座：c4–c5 打 d6。d6 一松，整条链子跟着松。","对着兵链找计划时只问一句：**哪个兵是底座，我用哪个兵去碰它？**"]},
  "po-chain": {"title":"兵链指向哪一翼，就在哪一翼进攻","text":["斜着连在一起的兵叫**兵链**。链头指向哪一边，你在那一边的空间就更多 —— **就在链头指向的那一翼进攻**，常常是用兵冲上去。","白方的兵链 d4–e5 或 e3–f4–e5，链头指向王翼，也就是黑王那一边。推 f 兵撞上去，打开黑王前面的线，让后和车进来。","三个局面都是这个方向：链头在 e5，f 兵往前冲。"]},
  "ps-break": {"title":"兵的突破：撞掉对方的支点","text":["黑方的 e5 兵是它整个阵地的**支点**：d6 象靠它站稳，中心靠它顶住。","你不能吃它（fxe5 只会让 d6 象吃回来更活跃），但你可以**从旁边撞**：f4–f5！封住黑方的象和后，把 e5 变成一个孤零零的目标。","兵的突破不总是为了吃兵 —— 常常是为了**改变格局**：换一个对自己有利的兵型。"]},
  "ps-minority": {"title":"少数兵进攻：用两个兵打三个","text":["后翼你只有 a、b 两个兵，对方有 a、b、c 三个 —— 反而是你去进攻，这叫**少数兵进攻**。目标不是吃兵，而是**制造弱点**。","推 b4–b5！兑掉之后对方要么留下一个孤兵 c6，要么留下一个落后兵 —— 你的车和马整个中局都有事可做。","这个计划在「卡尔斯巴德结构」里几乎每局都要用，值得记住。"]},
  "ps-bishops": {"title":"好象与坏象：兑掉对方的好象","text":["象走斜线，所以**站在和自己兵同色格上的象是坏象** —— 被自己的兵挡着。黑方 c8 象前面是 d5、e6 两个浅格兵，它几乎动不了。","e7 象则是黑方的**好象**，它走深格，正对着你的 d4、e5。你的 g5 象刚好也是深格象 —— Bxe7 把它换掉，黑方只剩下那个被兵堵死的坏象。","兑子原则：**兑掉对方的好子，留下他的坏子**。"]},
  "po-badb": {"title":"坏象：被自己的兵挡住的象","text":["象一辈子只走一种颜色的格子。如果自己的兵大多站在**和象同色的格子上**，象就被自己人挡住了 —— 这叫**坏象**。","对付坏象的原则：**换掉对方的好子，留下他的坏象**；然后让你的王和马走另一种颜色的格子，坏象永远够不着。","最后一个局面里，黑象的退路被它自己的兵堵死了 —— 坏象甚至会被捉死。"]},
  "po-color": {"title":"弱色格：少了一个象以后","text":["黑方走了 …g6 以后，f6、g7、h6 这些深格要靠深格象来守。**深格象一旦不在，王身边的深格就成了空洞**。","进攻的办法：让你的后、马、兵去占这些深格。f6 的兵、h6 的马、g7 的后，都是经典的杀法。","下面两个局面，黑方都没有深格象，各用两步杀王。"]},
  "po-prophy": {"title":"预防：先堵住对方的计划","text":["**预防**是一种想法：走自己的棋之前，先想想**对方下一步最想干什么**，然后让他干不成。","残局里最常见的预防：固定对方的兵，不让它前进或兑换；或者抢先占住对方的王想去的格子。","三个王兵残局，每一题都是「先不让他」的一步。"]},
  "ps-space": {"title":"空间优势：别急着换子","text":["c4 + e4 两个兵把 d5 格牢牢钳住，黑方的子挤在后三排 —— 这就是**空间优势**（这个结构叫「马洛奇钳制」）。","有空间的一方最怕**换子**：子越少，对方越不觉得挤。所以 Nxc6 是反着来；正确的是把马退到 c2 或 b3，或者用 f3 加固 e4，保持钳制。","空间多的时候记住：**留着子，慢慢挤**。"]},
};
